  public void SetCoreHardLocalBalanceV21(CoreHardBalanceDocumentV21 d){if(d!=null){if(coreHardV21==null||!CoreHardCallbacksConfiguredV21||d.schema!="core-hard-authored-initial-balance-v21"||d.sourceDifficulty!="Hard"||d.dungeonId!="DI_ALTERA_CORE_HARD"||d.difficultyValue!=1||d.npcLevel!=37||d.sourceArchiveOrdinal!=8||d.sourceRulesSha256!=coreHardV21.sourceRulesSha256||d.sourceModelSha256!=coreHardV21.sourceModelSha256||d.nativeStatsBound||d.runtimeAdmitted||d.actualBalanceVerified||d.productionBalanceApproved||!d.enabled||d.npcs==null||d.npcs.Length!=23||d.births==null||d.births.Length!=85||CoreHardBalanceReceiptV21(d)!=CoreHardBalanceReceiptExpectedV21)throw new ArgumentException("Changed exact Hard authored2D initial-value contract or unproven approval claim");if(CurrentRoom.id.StartsWith("Dungeon_Altera_Core_Hard-",StringComparison.Ordinal)&&enemies.Count>0)throw new InvalidOperationException("Local balance must be bound before source rooms are constructed; no mid-fight value changes");foreach(var n in d.npcs){NpcDefinition p;if(!npcDefinitions.TryGetValue(n.npc,out p)||p.physicalAttack!=n.sourcePhysical||p.magicAttack!=n.sourceMagic||n.hp<=0||n.physical<0||n.magic<0)throw new ArgumentException("Changed source profile or invalid authored values");}}coreHardBalanceV21=d;ClearCoreHardBalanceRoomV21();coreHardBalanceBirthEventsV21.Clear();}
